test.each(['leave_assigned_inbox_v1','leave_approval_counts_v1','leave_reads_context_v1','leave_calendar_v1'])('whole page %s failure terminates within bounded reads and explicit retry restores current data',async failed=>{
 identity(managerA);context={...personal,memberKind:'manager',capabilities:{...none,request:true,approve:true}};audiences=['own','assigned_team'];let failing=true
 const normal=mocks.rpc.getMockImplementation()!;mocks.rpc.mockImplementation((name,args)=>name===failed&&failing?{abortSignal:()=>Promise.resolve({data:null,error:{code:'55000'}})}:normal(name,args))
 const {client}=mount();fireEvent.click(await screen.findByRole('tab',{name:failed.includes('assigned')?'Persetujuan':'Kalender'}));await waitFor(()=>expect(mocks.rpc.mock.calls.some(([name])=>name===failed)).toBe(true));if(failed==='leave_approval_counts_v1')await screen.findByText('Fictional calendar employee');else await screen.findByText(failed==='leave_assigned_inbox_v1'?'Daftar persetujuan belum dapat dimuat. Coba muat ulang daftar.':failed==='leave_reads_context_v1'?'Akses kalender belum dapat dikonfirmasi.':'Kalender belum dapat dimuat.');await waitFor(()=>expect(client.isFetching()).toBe(0));const stopped=mocks.rpc.mock.calls.length;await act(async()=>{await new Promise(r=>setTimeout(r,40))});expect(mocks.rpc.mock.calls.length).toBe(stopped);expect(stopped).toBeLessThanOrEqual(9)
 failing=false;fireEvent(window,new Event('focus'));await waitFor(()=>expect(client.isFetching()).toBe(0));if(failed.includes('assigned'))expect(await screen.findByRole('button',{name:'Tinjau Fictional employee'})).toBeTruthy();else expect(await screen.findByText('Fictional calendar employee')).toBeTruthy();const recovered=mocks.rpc.mock.calls.length;await act(async()=>{await new Promise(r=>setTimeout(r,30))});expect(mocks.rpc.mock.calls.length).toBe(recovered);expect(recovered-stopped).toBeLessThanOrEqual(8)
})
