async function settledBudget(client:QueryClient,max:number){
 await waitFor(()=>expect(client.isFetching()).toBe(0));const calls=mocks.rpc.mock.calls.length
 await act(async()=>{await new Promise(resolve=>setTimeout(resolve,35))});expect(mocks.rpc.mock.calls.length).toBe(calls);expect(calls).toBeLessThanOrEqual(max);return calls
}
function adminActor(capability:'configure'|'adjust'|'readPrivate'|'manageAccess'='configure'){
 identity(hrA);context={...personal,memberKind:null,capabilities:{...none,[capability]:true},balances:[],currentPeriod:null};audiences=[]
 targets=[{id:employeeA,name:'Fictional target',capabilities:{configure:false,adjust:false,readPrivate:false,calendar:false,manageAccess:false,[capability]:true}}]
}
const groupId='85000000-0000-0000-0000-000000000001'
const calendarFixture={id:employeeB,name:'Fictional rota',version:1,effectiveFrom:'2026-10-01',effectiveUntil:null,timezone:'Etc/UTC',confirmedTimezone:'Etc/UTC',holidaysConfirmed:false,sundayMinutes:null,holidays:[],groups:[{id:groupId,name:'Fictional group',onAnchor:true}],impacts:{available:false,pendingCount:null,approvedCount:null}}
function setupOptions(){
 const normal=mocks.rpc.getMockImplementation()!
 mocks.rpc.mockImplementation((name,args)=>{
  if(name==='leave_admin_write_context_v1')return {abortSignal:()=>Promise.resolve({data:{...response(name,args),memberOptions:{state:'available',calendars:[{id:employeeB,name:'Fictional current lineage'}],groups:[{id:groupId,name:'Fictional group'}]}},error:null})}
  if(name==='leave_admin_setup_v1'&&['approvers','rota'].includes(args.p_section))return {abortSignal:()=>Promise.resolve({data:{rows:args.p_section==='rota'?[calendarFixture]:[{id:managerA,name:'Fictional approver',memberKind:'manager',active:true}],total:1,page:args.p_page,pageSize:args.p_page_size},error:null})}
  if(name==='leave_admin_rota_context_v1')return {abortSignal:()=>Promise.resolve({data:{calendarId:employeeB,scopeVersion:context.scopeVersion,authorityKey:'a'.repeat(64),calendar:calendarFixture},error:null})}
  if(name==='leave_calendar_preview_v1')return {abortSignal:()=>Promise.resolve({data:{calendarId:employeeB,calendarVersion:1,fingerprint:'calendar-fingerprint',impacts:{available:true,pendingCount:0,approvedCount:0}},error:null})}
  if(name==='leave_roster_preview_v1')return {abortSignal:()=>Promise.resolve({data:{calendarId:employeeB,calendarVersion:2,fingerprint:'server-fingerprint',rows:[{date:'2026-10-10',groupId,capacityMinutes:225}],impacts:{available:true,pendingCount:0,approvedCount:0}},error:null})}
  return normal(name,args)
 })
}
